&lt;ul data-path-to-node=&quot;13&quot;&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;13,0,0&quot;&gt;&lt;strong data-path-to-node=&quot;13,0,0&quot; data-index-in-node=&quot;0&quot;&gt;Relevant Experience:&lt;/strong&gt; Background in administrative support, corporate reception, workplace experience, or physical security operations.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
